n  // 并按 maptalks SpatialReference.loadArcgis 的 parse 逻辑构造空间参考与瓦片系统。\\r\\n  fetch(arcUrl + \\"?f=json\\")\\r\\n    .then(function (res) {\\r\\n      return res.json();\\r\\n    })\\r\\n    .then(function (json) {\\r\\n      const tileInfo = json.tileInfo;\\r\\n      const resolutions = [];\\r\\n      for (let i = 0; i < tileInfo.lods.length; i++) {\\r\\n        resolutions.push(tileInfo.lods[i].resolution);\\r\\n      }\\r\\n      const ref = {\\r\\n        resolutions: resolutions,\\r\\n        projection: \\"EPSG:3857\\",\\r\\n        fullExtent: null,\\r\\n      };\\r\\n      const map = new Map(\\"map\\", {\\r\\n        center: [121, 0],\\r\\n        zoom: 1,\\r\\n        minZoom: 1,\\r\\n        maxZoom: 16,\\r\\n        spatialReference: ref,\\r\\n        baseLayer: new TileLayer(\\"base\\", {\\r\\n          tileSystem: [1, -1, tileInfo.origin.x, tileInfo.origin.y],\\r\\n          tileSize: [tileInfo.cols, tileInfo.rows],\\r\\n          urlTemplate: arcUrl + \\"/tile/{z}/{y}/{x}\\",\\r\\n          attribution: '&copy; <a target=\\"_blank\\" href=\\"' + arcUrl + '\\">ArcGIS</a>',\\r\\n        }),\\r\\n      });\\r\\n    })\\r\\n    .catch(function (err) {\\r\\n      throw err;\\r\\n    });\\r\\n<\/script>\\r\\n\\r\\n<style>\\r\\n  @import \\"https://maptalks.com/api/maptalks.css\\";\\r\\n  @import \\"./index.css\\";\\r\\n</style>\\r\\n","description":"","files":{"index.css":"html,\\r\\nbody {\\r\\n  margin: 0px;\\r\\n  height: 100%;\\r\\n  width: 100%;\\r\\n}\\r\\n\\r\\n.container {\\r\\n  width: 100%;\\r\\n  height: 100%;\\r\\n}\\r\\n","index.html":"<div id=\\"map\\" class=\\"container\\"></div>\\r\\n\\r\\n<script type=\\"module\\">\\r\\n  import { Map, TileLayer } from \\"maptalks\\";\\r\\n\\r\\n  const arcUrl =\\r\\n    \\"https://server.arcgisonline.com/arcgis/rest/services/World_Imagery/MapServer\\";\\r\\n\\r\\n  // REPL 预览 iframe 里 maptalks 默认的 loadArcgis(JSONP) 会静默失败（脚本回调不触发），\\r\\n  // 这里改用 fetch（ArcGIS 服务返回 Access-Control-Allow-Origin: *，允许 CORS）拉取元数据，\\r\\n  // 并按 maptalks SpatialReference.loadArcgis 的 parse 逻辑构造空间参考与瓦片系统。\\r\\n  fetch(arcUrl + \\"?f=json\\")\\r\\n    .then(function (res) {\\r\\n      return res.json();\\r\\n    })\\r\\n    .then(function (json) {\\r\\n      const tileInfo = json.tileInfo;\\r\\n      const resolutions = [];\\r\\n      for (let i = 0; i < tileInfo.lods.length; i++) {\\r\\n        resolutions.push(tileInfo.lods[i].resolution);\\r\\n      }\\r\\n      const ref = {\\r\\n        resolutions: resolutions,\\r\\n        projection: \\"EPSG:3857\\",\\r\\n        fullExtent: null,\\r\\n      };\\r\\n      const map = new Map(\\"map\\", {\\r\\n        center: [121, 0],\\r\\n        zoom: 1,\\r\\n        minZoom: 1,\\r\\n        maxZoom: 16,\\r\\n        spatialReference: ref,\\r\\n        baseLayer: new TileLayer(\\"base\\", {\\r\\n          tileSystem: [1, -1, tileInfo.origin.x, tileInfo.origin.y],\\r\\n          tileSize: [tileInfo.cols, tileInfo.rows],\\r\\n          urlTemplate: arcUrl + \\"/tile/{z}/{y}/{x}\\",\\r\\n          attribution: '&copy; <a target=\\"_blank\\" href=\\"' + arcUrl + '\\">ArcGIS</a>',\\r\\n        }),\\r\\n      });\\r\\n    })\\r\\n    .catch(function (err) {\\r\\n      throw err;\\r\\n    });\\r\\n<\/script>\\r\\n\\r\\n<style>\\r\\n  @import \\"https://maptalks.com/api/maptalks.css\\";\\r\\n  @import \\"./index.css\\";\\r\\n</style>\\r\\n"}},{"path":"basic/tilelayer-projection/baidu","category":"basic","subcategory":"tilelayer-projection","name":"baidu","html":"<div id=\\"map\\" class=\\"container\\"></div>\\r\\n\\r\\n<script type=\\"module\\">\\r\\n  import { Map, TileLayer } from \\"maptalks\\";\\r\\n\\r\\n  const map = new Map(\\"map\\", {\\r\\n    center: [105.08052356963802, 36.04231948670001],\\r\\n    zoom: 5,\\r\\n    minZoom: 1,\\r\\n    maxZoom: 19,\\r\\n    spatialReference: {\\r\\n      projection: \\"baidu\\",\\r\\n    },\\r\\n    baseLayer: new TileLayer(\\"base\\", {\\r\\n      urlTemplate:\\r\\n        \\"https://gss{s}.bdstatic.com/8bo_dTSlRsgBo1vgoIiO_jowehsv/tile/?qt=tile&x={x}&y={y}&z={z}&styles=pl&scaler=1&udt=20170927\\",\\r\\n      subdomains: [0, 1, 2, 3],\\r\\n      attribution:\\r\\n        '&copy; <a target=\\"_blank\\" href=\\"http://map.baidu.com\\">Baidu</a>',\\r\\n    }),\\r\\n  });\\r\\n<\/script>\\r\\n\\r\\n<style>\\r\\n  @import \\"https://maptalks.com/api/maptalks.css\\";\\r\\n  @import \\"./index.css\\";\\r\\n</style>\\r\\n","description":"","files":{"index.css":"html,\\r\\nbody {\\r\\n  margin: 0px;\\r\\n  height: 100%;\\r\\n  width: 100%;\\r\\n}\\r\\n\\r\\n.container {\\r\\n  width: 100%;\\r\\n  height: 100%;\\r\\n}\\r\\n","index.html":"<div id=\\"map\\" class=\\"container\\"></div>\\r\\n\\r\\n<script type=\\"module\\">\\r\\n  import { Map, TileLayer } from \\"maptalks\\";\\r\\n\\r\\n  const map = new Map(\\"map\\", {\\r\\n    center: [105.08052356963802, 36.04231948670001],\\r\\n    zoom: 5,\\r\\n    minZoom: 1,\\r\\n    maxZoom: 19,\\r\\n    spatialReference: {\\r\\n      projection: \\"baidu\\",\\r\\n    },\\r\\n    baseLayer: new TileLayer(\\"base\\", {\\r\\n      urlTemplate:\\r\\n        \\"https://gss{s}.bdstatic.com/8bo_dTSlRsgBo1vgoIiO_jowehsv/tile/?qt=tile&x={x}&y={y}&z={z}&styles=pl&scaler=1&udt=20170927\\",\\r\\n      subdomains: [0, 1, 2, 3],\\r\\n      attribution:\\r\\n        '&copy; <a target=\\"_blank\\" href=\\"http://map.baidu.com\\">Baidu</a>',\\r\\n    }),\\r\\n  });\\r\\n<\/script>\\r\\n\\r\\n<style>\\r\\n  @import \\"https://maptalks.com/api/maptalks.css\\";\\r\\n  @import \\"./index.css\\";\\r\\n</style>\\r\\n"}},{"path":"basic/tilelayer-projection/base64","category":"basic","subcategory":"tilelayer-projection","name":"base64","html":"<div id=\\"map\\" class=\\"container\\"></div>\\r\\n\\r\\n<script type=\\"module\\">\\r\\n  import { Map, TileLayer } from \\"maptalks\\";\\r\\n\\r\\n  const baseLayer = new TileLayer(\\"base\\", {\\r\\n    urlTemplate: \\"https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}.png\\",\\r\\n    subdomains: [\\"a\\", \\"b\\", \\"c\\", \\"d\\"],\\r\\n    attribution:\\r\\n      \\"&copy; <a href='http://osm.org'>OpenStreetMap</a> contributors, &copy; <a href='https://carto.com/'>CARTO</a>\\",\\r\\n  });\\r\\n\\r\\n  // generate tile url\\r\\n  baseLayer.getTileUrl = function (x, y, z) {\\r\\n    // replace with your own\\r\\n    // e.g. return a url pointing to your sqlite database\\r\\n    return TileLayer.prototype.getTileUrl.call(this, x, y, z);\\r\\n  };\\r\\n\\r\\n  baseLayer.on(\\"renderercreate\\", function (e) {\\r\\n    // load tile image\\r\\n    // img(Image): an Image object\\r\\n    // url(String): the url of the tile\\r\\n    e.renderer.loadTileImage = function (img, url) {\\r\\n      // mocking getting image's base64\\r\\n      // replace it by your own, e.g. load from sqlite database\\r\\n      const remoteImage = new Image();\\r\\n      remoteImage.crossOrigin = \\"anonymous\\";\\r\\n      remoteImage.onload = function () {\\r\\n        const base64 = getBase64Image(remoteImage);\\r\\n        img.src = base64;\\r\\n      };\\r\\n      remoteImage.src = url;\\r\\n    };\\r\\n  });\\r\\n\\r\\n  function getBase64Image(img) {\\r\\n    const canvas = document.createElement(\\"canvas\\");\\r\\n    canvas.width = img.width;\\r\\n    canvas.height = img.height;\\r\\n\\r\\n    const ctx = canvas.getContext(\\"2d\\");\\r\\n    ctx.drawImage(img, 0, 0);\\r\\n\\r\\n    const dataURL = canvas.toDataURL(\\"image/png\\");\\r\\n    return dataURL;\\r\\n  }\\r\\n\\r\\n  const map = new Map(\\"map\\", {\\r\\n    center: [-0.113049, 51.498568],\\r\\n    zoom: 11,\\r\\n    baseLayer: baseLayer,\\r\\n  });\\r\\n<\/script>\\r\\n\\r\\n<style>\\r\\n  @import \\"https://maptalks.com/api/maptalks.css\\";\\r\\n  @import \\"./index.css\\";\\r\\n</style>\\r\\n","description":"","files":{"index.css":"html,\\r\\nbody {\\r\\n  margin: 0px;\\r\\n  height: 100%;\\r\\n  width: 100%;\\r\\n}\\r\\n\\r\\n.container {\\r\\n  width: 100%;\\r\\n  height: 100%;\\r\\n}\\r\\n","index.html":"<div id=\\"map\\" class=\\"container\\"></div>\\r\\n\\r\\n<script type=\\"module\\">\\r\\n  import { Map, TileLayer } from \\"maptalks\\";\\r\\n\\r\\n  const baseLayer = new TileLayer(\\"base\\", {\\r\\n    urlTemplate: \\"https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}.png\\",\\r\\n    subdomains: [\\"a\\", \\"b\\", \\"c\\", \\"d\\"],\\r\\n    attribution:\\r\\n      \\"&copy; <a href='http://osm.org'>OpenStreetMap</a> contributors, &copy; <a href='https://carto.com/'>CARTO</a>\\",\\r\\n  });\\r\\n\\r\\n  // generate tile url\\r\\n  baseLayer.getTileUrl = function (x, y, z) {\\r\\n    // replace with your own\\r\\n    // e.g. return a url pointing to your sqlite database\\r\\n    return TileLayer.prototype.getTileUrl.call(this, x, y, z);\\r\\n  };\\r\\n\\r\\n  baseLayer.on(\\"renderercreate\\", function (e) {\\r\\n    // load tile image\\r\\n    // img(Image): an Image object\\r\\n    // url(String): the url of the tile\\r\\n    e.renderer.loadTileImage = function (img, url) {\\r\\n      // mocking getting image's base64\\r\\n      // replace it by your own, e.g. load from sqlite database\\r\\n      const remoteImage = new Image();\\r\\n      remoteImage.crossOrigin = \\"anonymous\\";\\r\\n      remoteImage.onload = function () {\\r\\n        const base64 = getBase64Image(remoteImage);\\r\\n        img.src = base64;\\r\\n      };\\r\\n      remoteImage.src = url;\\r\\n    };\\r\\n  });\\r\\n\\r\\n  function getBase64Image(img) {\\r\\n    const canvas = document.createElement(\\"canvas\\");\\r\\n    canvas.width = img.width;\\r\\n    canvas.height = img.height;\\r\\n\\r\\n    const ctx = canvas.getContext(\\"2d\\");\\r\\n    ctx.drawImage(img, 0, 0);\\r\\n\\r\\n    const dataURL = canvas.toDataURL(\\"image/png\\");\\r\\n    return dataURL;\\r\\n  }\\r\\n\\r\\n  const map = new Map(\\"map\\", {\\r\\n    center: [-0.113049, 51.498568],\\r\\n    zoom: 11,\\r\\n    baseLayer: baseLayer,\\r\\n  });\\r\\n<\/script>\\r\\n\\r\\n<style>\\r\\n  @import \\"https://maptalks.com/api/maptalks.css\\";\\r\\n  @import \\"./index.css\\";\\r\\n</style>\\r\\n"}},{"path":"basic/tilelayer-projection/canvas-renderer","category":"basic","subcategory":"tilelayer-projection","name":"canvas-renderer","html":"<div id=\\"map\\" class=\\"container\\"></div>\\r\\n\\r\\n<script type=\\"module\\">\\r\\n  import { Map, TileLayer } from \\"maptalks\\";\\r\\n\\r\\n  const map = new Map(\\"map\\", {\\r\\n    center: [-0.113049, 51.498568],\\r\\n    zoom: 13,\\r\\n    baseLayer: new TileLayer(\\"base\\", {\\r\\n      renderer: \\"canvas\\", // set TileLayer's renderer to canvas\\r\\n      // crossOrigin : 'anonymous',\\r\\n      urlTemplate:\\r\\n        \\"https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}.png\\",\\r\\n      subdomains: [\\"a\\", \\"b\\", \\"c\\", \\"d\\"],\\r\\n      attribution:\\r\\n        \\"&copy; <a href='http://osm.org'>OpenStreetMap</a> contributors, &copy; <a href='https://carto.com/'>CARTO</a>\\",\\r\\n    }),\\r\\n  });\\r\\n<\/script>\\r\\n\\r\\n<style>\\r\\n  @import \\"https://maptalks.com/api/maptalks.css\\";\\r\\n  @import \\"./index.css\\";\\r\\n</style>\\r\\n","description":"","files":{"index.css":"html,\\r\\nbody {\\r\\n  margin: 0px;\\r\\n  height: 100%;\\r\\n  width: 100%;\\r\\n}\\r\\n\\r\\n.container {\\r\\n  width: 100%;\\r\\n  height: 100%;\\r\\n}\\r\\n","index.html":"<div id=\\"map\\" class=\\"container\\"></div>\\r\\n\\r\\n<script type=\\"module\\">\\r\\n  import { Map, TileLayer } from \\"maptalks\\";\\r\\n\\r\\n  const map = new Map(\\"map\\", {\\r\\n    center: [-0.113049, 51.498568],\\r\\n    zoom: 13,\\r\\n    baseLayer: new TileLayer(\\"base\\", {\\r\\n      renderer: \\"canvas\\", // set TileLayer's renderer to canvas\\r\\n      // crossOrigin : 'anonymous',\\r\\n      urlTemplate:\\r\\n        \\"https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}.png\\",\\r\\n      subdomains: [\\"a\\", \\"b\\", \\"c\\", \\"d\\"],\\r\\n      attribution:\\r\\n        \\"&copy; <a href='http://osm.org'>OpenStreetMap</a> contributors, &copy; <a href='https://carto.com/'>CARTO</a>\\",\\r\\n    }),\\r\\n  });\\r\\n<\/script>\\r\\n\\r\\n<style>\\r\\n  @import \\"https://maptalks.com/api/maptalks.css\\";\\r\\n  @import \\"./index.css\\";\\r\\n</style>\\r\\n"}},{"path":"basic/tilelayer-projection/custom-tile","category":"basic","subcategory":"tilelayer-projection","name":"custom-tile","html":"<div id=\\"map\\" class=\\"container\\"></div>\\r\\n\\r\\n<script type=\\"module\\">\\r\\n  import { Map, TileLayer } from \\"maptalks\\";\\r\\n\\r\\n  // A complete customized TileLayer\\r\\n  // Radius of the earth\\r\\n  const earchRadiusInMeters = 6378137;\\r\\n  const inchPerMeter = 1 / 0.0254;\\r\\n  const meterPerMapUnit = (Math.PI * 2 * earchRadiusInMeters) / 360;\\r\\n\\r\\n  function replaceURL(url, x, y, scale) {\\r\\n    const str = [\\"x\\", x, \\"y\\", y, \\"scale\\", scale];\\r\\n    for (let i = 0, len = str.length; i < len; i += 2) {\\r\\n      url = url.replace(\\"{\\" + str[i] + \\"}\\", str[i + 1]);\\r\\n    }\\r\\n    return url;\\r\\n  }\\r\\n\\r\\n  function resolutionToScale(resolution, dpi) {\\r\\n    let scale = resolution * dpi * inchPerMeter * meterPerMapUnit;\\r\\n    scale = 1 / scale;\\r\\n    return scale;\\r\\n  }\\r\\n\\r\\n  const parmas = {\\r\\n    zooms: 5,\\r\\n    firstRes: 0.009507170090264933,\\r\\n    origin: [114.59, 42.31],\\r\\n    maxBounds: [\\r\\n      [-180, -90],\\r\\n      [180, 90],\\r\\n    ],\\r\\n  };\\r\\n\\r\\n  const url =\\r\\n    \\"https://iserver.supermap.io/iserver/services/map-jingjin/rest/maps/%E4%BA%AC%E6%B4%A5%E5%9C%B0%E5%8C%BA%E5%9C%B0%E5%9B%BE/tileImage.png?width=256&height=256&redirect=false&transparent=true&cacheEnabled=true&origin=%7B%22x%22%3A114.59%2C%22y%22%3A42.31%7D&overlapDisplayed=false&scale={scale}&x={x}&y={y}\\";\\r\\n  const res = [];\\r\\n  for (let i = 0; i <= parmas.zooms; i++) {\\r\\n    res.push(parmas.firstRes / Math.pow(2, i));\\r\\n  }\\r\\n  const crs = {\\r\\n    projection: \\"EPSG:4326\\",\\r\\n    resolutions: res,\\r\\n    fullExtent: {\\r\\n      top: 42.31,\\r\\n      left: 114.59,\\r\\n      bottom: 37.44232891378436,\\r\\n      right: 119.45767108621564,\\r\\n    },\\r\\n  };\\r\\n\\r\\n  const tileLayer = new TileLayer(\\"base\\", {\\r\\n    repeatWorld: true,\\r\\n    urlTemplate: url,\\r\\n    spatialReference: crs,\\r\\n    subdomains: [\\"a\\", \\"b\\", \\"c\\", \\"d\\"],\\r\\n    attribution:\\r\\n      '&copy; <a href=\\"https://www.supermap.com/cn/\\">supermap</a> contributors',\\r\\n    tileSystem: [1, -1].concat(parmas.origin), // tile system\\r\\n  });\\r\\n\\r\\n  // custom tilelayer getTileUrl\\r\\n  tileLayer.getTileUrl = function (x, y, z) {\\r\\n    this.scales = this.scales || {};\\r\\n    if (this.scales[z]) {\\r\\n      return replaceURL(this.options.urlTemplate, x, y, this.scales[z]);\\r\\n    }\\r\\n    const crs = this.getMap().getSpatialReference().getProjection();\\r\\n    const bounds = this._getTileExtent(x, y, z);\\r\\n    const min = bounds.getMin(),\\r\\n      max = bounds.getMax();\\r\\n    const ne = crs.project(max);\\r\\n    const sw = crs.project(min);\\r\\n    const tileSize = this.options.tileSize[0];\\r\\n    const resolution = Math.max(\\r\\n      Math.abs(ne.x - sw.x) / tileSize,\\r\\n      Math.abs(ne.y - sw.y) / tileSize\\r\\n    );\\r\\n    const scale = resolutionToScale(resolution, 96);\\r\\n    this.scales[z] = scale;\\r\\n    return replaceURL(this.options.urlTemplate, x, y, this.scales[z]);\\r\\n  };\\r\\n\\r\\n  tileLayer._getTileExtent = function (x, y, z) {\\r\\n    const map = this.getMap(),\\r\\n      res = map._getResolution(z),\\r\\n      tileConfig = this._getTileConfig(),\\r\\n      tileExtent = tileConfig.getTilePrjExtent(x, y, res);\\r\\n    return tileExtent;\\r\\n  };\\r\\n\\r\\n  const map = new Map(\\"map\\", {\\r\\n    center: [116.85, 39.79],\\r\\n    // pitch:40,\\r\\n    zoom: 0,\\r\\n    spatialReference: crs,\\r\\n    baseLayer: tileLayer,\\r\\n  });\\r\\n<\/script>\\r\\n\\r\\n<style>\\r\\n  @import \\"https://maptalks.com/api/maptalks.css\\";\\r\\n  @import \\"./index.css\\";\\r\\n</style>\\r\\n","description":"","files":{"index.css":"html,\\r\\nbody {\\r\\n  margin: 0px;\\r\\n  height: 100%;\\r\\n  width: 100%;\\r\\n}\\r\\n\\r\\n.container {\\r\\n  width: 100%;\\r\\n  height: 100%;\\r\\n}\\r\\n","index.html":"<div id=\\"map\\" class=\\"container\\"></div>\\r\\n\\r\\n<script type=\\"module\\">\\r\\n  import { Map, TileLayer } from \\"maptalks\\";\\r\\n\\r\\n  // A complete customized TileLayer\\r\\n  // Radius of the earth\\r\\n  const earchRadiusInMeters = 6378137;\\r\\n  const inchPerMeter = 1 / 0.0254;\\r\\n  const meterPerMapUnit = (Math.PI * 2 * earchRadiusInMeters) / 360;\\r\\n\\r\\n  function replaceURL(url, x, y, scale) {\\r\\n    const str = [\\"x\\", x, \\"y\\", y, \\"scale\\", scale];\\r\\n    for (let i = 0, len = str.length; i < len; i += 2) {\\r\\n      url = url.replace(\\"{\\" + str[i] + \\"}\\", str[i + 1]);\\r\\n    }\\r\\n    return url;\\r\\n  }\\r\\n\\r\\n  function resolutionToScale(resolution, dpi) {\\r\\n    let scale = resolution * dpi * inchPerMeter * meterPerMapUnit;\\r\\n    scale = 1 / scale;\\r\\n    return scale;\\r\\n  }\\r\\n\\r\\n  const parmas = {\\r\\n    zooms: 5,\\r\\n    firstRes: 0.009507170090264933,\\r\\n    origin: [114.59, 42.31],\\r\\n    maxBounds: [\\r\\n      [-180, -90],\\r\\n      [180, 90],\\r\\n    ],\\r\\n  };\\r\\n\\r\\n  const url =\\r\\n    \\"https://iserver.supermap.io/iserver/services/map-jingjin/rest/maps/%E4%BA%AC%E6%B4%A5%E5%9C%B0%E5%8C%BA%E5%9C%B0%E5%9B%BE/tileImage.png?width=256&height=256&redirect=false&transparent=true&cacheEnabled=true&origin=%7B%22x%22%3A114.59%2C%22y%22%3A42.31%7D&overlapDisplayed=false&scale={scale}&x={x}&y={y}\\";\\r\\n  const res = [];\\r\\n  for (let i = 0; i <= parmas.zooms; i++) {\\r\\n    res.push(parmas.firstRes / Math.pow(2, i));\\r\\n  }\\r\\n  const crs = {\\r\\n    projection: \\"EPSG:4326\\",\\r\\n    resolutions: res,\\r\\n    fullExtent: {\\r\\n      top: 42.31,\\r\\n      left: 114.59,\\r\\n      bottom: 37.44232891378436,\\r\\n      right: 119.45767108621564,\\r\\n    },\\r\\n  };\\r\\n\\r\\n  const tileLayer = new TileLayer(\\"base\\", {\\r\\n    repeatWorld: true,\\r\\n    urlTemplate: url,\\r\\n    spatialReference: crs,\\r\\n    subdomains: [\\"a\\", \\"b\\", \\"c\\", \\"d\\"],\\r\\n    attribution:\\r\\n      '&copy; <a href=\\"https://www.supermap.com/cn/\\">supermap</a> contributors',\\r\\n    tileSystem: [1, -1].concat(parmas.origin), // tile system\\r\\n  });\\r\\n\\r\\n  // custom tilelayer getTileUrl\\r\\n  tileLayer.getTileUrl = function (x, y, z) {\\r\\n    this.scales = this.scales || {};\\r\\n    if (this.scales[z]) {\\r\\n      return replaceURL(this.options.urlTemplate, x, y, this.scales[z]);\\r\\n    }\\r\\n    const crs = this.getMap().getSpatialReference().getProjection();\\r\\n    const bounds = this._getTileExtent(x, y, z);\\r\\n    const min = bounds.getMin(),\\r\\n      max = bounds.getMax();\\r\\n    const ne = crs.project(max);\\r\\n    const sw = crs.project(min);\\r\\n    const tileSize = this.options.tileSize[0];\\r\\n    const resolution = Math.max(\\r\\n      Math.abs(ne.x - sw.x) / tileSize,\\r\\n      Math.abs(ne.y - sw.y) / tileSize\\r\\n    );\\r\\n    const scale = resolutionToScale(resolution, 96);\\r\\n    this.scales[z] = scale;\\r\\n    return replaceURL(this.options.urlTemplate, x, y, this.scales[z]);\\r\\n  };\\r\\n\\r\\n  tileLayer._getTileExtent = function (x, y, z) {\\r\\n    const map = this.getMap(),\\r\\n      res = map._getResolution(z),\\r\\n      tileConfig = this._getTileConfig(),\\r\\n      tileExtent = tileConfig.getTilePrjExtent(x, y, res);\\r\\n    return tileExtent;\\r\\n  };\\r\\n\\r\\n  const map = new Map(\\"map\\", {\\r\\n    center: [116.85, 39.79],\\r\\n    // pitch:40,\\r\\n    zoom: 0,\\r\\n    spatialReference: crs,\\r\\n    baseLayer: tileLayer,\\r\\n  });\\r\\n<\/script>\\r\\n\\r\\n<style>\\r\\n  @import \\"https://maptalks.com/api/maptalks.css\\";\\r\\n  @import \\"./index.css\\";\\r\\n</style>\\r\\n"}},{"path":"basic/tilelayer-projection/d3-proj","category":"basic","subcategory":"tilelayer-projection","name":"d3-proj","html":"<div id=\\"map\\" class=\\"container\\">loading data...</div>\\r\\n<script src=\\"https://d3js.org/d3.v4.min.js\\"><\/script>\\r\\n<script src=\\"https://d3js.org/topojson.v2.min.js\\"><\/script>\\r\\n\\r\\n<script type=\\"module\\">\\r\\n  import * as maptalks from \\"maptalks\\";\\r\\n  import d3 from \\"d3v4\\";\\r\\n  window.d3 = d3;\\r\\n  import * as topojson from \\"topojson-client\\";\\r\\n  window.topojson = topojson;\\r\\n\\r\\n  // Versor Dragging projection from D3\\r\\n  // https://bl.ocks.org/mbostock/7ea1dde508cec6d2d95306f92642bc42\\r\\n  const projection = d3.geoOrthographic().scale(148).precision(0.1);\\r\\n\\r\\n  // convert to a maptalks projection object\\r\\n  const proj = {\\r\\n    project: function (c) {\\r\\n      const pc = projection([c.x, c.y]);\\r\\n      // orthographic 投影对背面/极点可能返回 null，兜底返回原坐标，避免 null[0] 崩溃\\r\\n      if (!pc || isNaN(pc[0]) || isNaN(pc[1])) {\\r\\n        return new maptalks.Coordinate(c.x, c.y);\\r\\n      }\\r\\n      return new maptalks.Coordinate(pc[0], pc[1]);\\r\\n    },\\r\\n    unproject: function (pc) {\\r\\n      const c = projection.invert([pc.x, pc.y]);\\r\\n      if (!c || isNaN(c[0]) || isNaN(c[1])) {\\r\\n        return null;\\r\\n      }\\r\\n      return new maptalks.Coordinate(c);\\r\\n    },\\r\\n  };\\r\\n\\r\\n  const min = proj.project(new maptalks.Coordinate(-180, -90)),\\r\\n    max = proj.project(new maptalks.Coordinate(180, 90)),\\r\\n    fullExtent = {\\r\\n      top: max.y,\\r\\n      left: min.x,\\r\\n      right: max.x,\\r\\n      bottom: min.y,\\r\\n    };\\r\\n\\r\\n  // REPL iframe 里 d3 v4 的 d3.json（XHR）会报错，改用 fetch 加载 GeoJSON\\r\\n  fetch(\\"{res}/geojson/world-50m.json\\")\\r\\n    .then(function (res) {\\r\\n      return res.json();\\r\\n    })\\r\\n    .then(function (world) {\\r\\n      // initialize map with a customized projection\\r\\n      const map = new maptalks.Map(\\"map\\", {\\r\\n        center: [0, 0],\\r\\n        centerCross: true,\\r\\n        zoom: 2,\\r\\n        spatialReference: {\\r\\n          projection: proj,\\r\\n          resolutions: (function () {\\r\\n            const resolutions = [];\\r\\n            for (let i = 0; i < 10; i++) {\\r\\n              resolutions[i] = 4 / Math.pow(2, i);\\r\\n            }\\r\\n            return resolutions;\\r\\n          })(),\\r\\n          fullExtent: fullExtent,\\r\\n        },\\r\\n      });\\r\\n      const featureCollection = topojson.feature(world, world.objects.countries),\\r\\n        geometries = maptalks.GeoJSON.toGeometry(featureCollection);\\r\\n      const symbol = {\\r\\n        lineColor: \\"#fff\\",\\r\\n        lineWidth: 0.5,\\r\\n        polygonOpacity: 1,\\r\\n        polygonFill: \\"#747474\\",\\r\\n      };\\r\\n      new maptalks.VectorLayer(\\"v\\", geometries, {\\r\\n        geometryEvents: false,\\r\\n        enableSimplify: false,\\r\\n      })\\r\\n        .forEach(function (geo) {\\r\\n          geo.setSymbol(symbol);\\r\\n        })\\r\\n        .addTo(map);\\r\\n    })\\r\\n    .catch(function (err) {\\r\\n      throw err;\\r\\n    });\\r\\n<\/script>\\r\\n\\r\\n<style>\\r\\n  @import \\"https://maptalks.com/api/maptalks.css\\";\\r\\n  @import \\"./index.css\\";\\r\\n</style>\\r\\n","description":"","files":{"index.css":"html,\\r\\nbody {\\r\\n  margin: 0px;\\r\\n  height: 100%;\\r\\n  width: 100%;\\r\\n}\\r\\n\\r\\n.container {\\r\\n  width: 100%;\\r\\n  height: 100%;\\r\\n}\\r\\n","index.html":"<div id=\\"map\\" class=\\"container\\">loading data...</div>\\r\\n<script src=\\"https://d3js.org/d3.v4.min.js\\"><\/script>\\r\\n<script src=\\"https://d3js.org/topojson.v2.min.js\\"><\/script>\\r\\n\\r\\n<script type=\\"module\\">\\r\\n  import * as maptalks from \\"maptalks\\";\\r\\n  import d3 from \\"d3v4\\";\\r\\n  window.d3 = d3;\\r\\n  import * as topojson from \\"topojson-client\\";\\r\\n  window.topojson = topojson;\\r\\n\\r\\n  // Versor Dragging projection from D3\\r\\n  // https://bl.ocks.org/mbostock/7ea1dde508cec6d2d95306f92642bc42\\r\\n  const projection = d3.geoOrthographic().scale(148).precision(0.1);\\r\\n\\r\\n  // convert to a maptalks projection object\\r\\n  const proj = {\\r\\n    project: function (c) {\\r\\n      const pc = projection([c.x, c.y]);\\r\\n      // orthographic 投影对背面/极点可能返回 null，兜底返回原坐标，避免 null[0] 崩溃\\r\\n      if (!pc || isNaN(pc[0]) || isNaN(pc[1])) {\\r\\n        return new maptalks.Coordinate(c.x, c.y);\\r\\n      }\\r\\n      return new maptalks.Coordinate(pc[0], pc[1]);\\r\\n    },\\r\\n    unproject: function (pc) {\\r\\n      const c = projection.invert([pc.x, pc.y]);\\r\\n      if (!c || isNaN(c[0]) || isNaN(c[1])) {\\r\\n        return null;\\r\\n      }\\r\\n      return new maptalks.Coordinate(c);\\r\\n    },\\r\\n  };\\r\\n\\r\\n  const min = proj.project(new maptalks.Coordinate(-180, -90)),\\r\\n    max = proj.project(new maptalks.Coordinate(180, 90)),\\r\\n    fullExtent = {\\r\\n      top: max.y,\\r\\n      left: min.x,\\r\\n      right: max.x,\\r\\n      bottom: min.y,\\r\\n    };\\r\\n\\r\\n  // REPL iframe 里 d3 v4 的 d3.json（XHR）会报错，改用 fetch 加载 GeoJSON\\r\\n  fetch(\\"{res}/geojson/world-50m.json\\")\\r\\n    .then(function (res) {\\r\\n      return res.json();\\r\\n    })\\r\\n    .then(function (world) {\\r\\n      // initialize map with a customized projection\\r\\n      const map = new maptalks.Map(\\"map\\", {\\r\\n        center: [0, 0],\\r\\n        centerCross: true,\\r\\n        zoom: 2,\\r\\n        spatialReference: {\\r\\n          projection: proj,\\r\\n          resolutions: (function () {\\r\\n            const resolutions = [];\\r\\n            for (let i = 0; i < 10; i++) {\\r\\n              resolutions[i] = 4 / Math.pow(2, i);\\r\\n            }\\r\\n            return resolutions;\\r\\n          })(),\\r\\n          fullExtent: fullExtent,\\r\\n        },\\r\\n      });\\r\\n      const featureCollection = topojson.feature(world, world.objects.countries),\\r\\n        geometries = maptalks.GeoJSON.toGeometry(featureCollection);\\r\\n      const symbol = {\\r\\n        lineColor: \\"#fff\\",\\r\\n        lineWidth: 0.5,\\r\\n        polygonOpacity: 1,\\r\\n        polygonFill: \\"#747474\\",\\r\\n      };\\r\\n      new maptalks.VectorLayer(\\"v\\", geometries, {\\r\\n        geometryEvents: false,\\r\\n        enableSimplify: false,\\r\\n      })\\r\\n        .forEach(function (geo) {\\r\\n          geo.setSymbol(symbol);\\r\\n        })\\r\\n        .addTo(map);\\r\\n    })\\r\\n    .catch(function (err) {\\r\\n      throw err;\\r\\n    });\\r\\n<\/script>\\r\\n\\r\\n<style>\\r\\n  @import \\"https://maptalks.com/api/maptalks.css\\";\\r\\n  @import \\"./index.css\\";\\r\\n</style>\\r\\n","index.js":"// Versor Dragging projection from D3\\r\\n// https://bl.ocks.org/mbostock/7ea1dde508cec6d2d95306f92642bc42\\r\\nconst projection = d3.geoOrthographic().scale(148).precision(0.1);\\r\\n\\r\\n// convert to a maptalks projection object\\r\\nconst proj = {\\r\\n  project: function (c) {\\r\\n    const pc = projection([c.x, c.y]);\\r\\n    return new maptalks.Coordinate(pc[0], pc[1]);\\r\\n  },\\r\\n  unproject: function (pc) {\\r\\n    const c = projection.invert([pc.x, pc.y]);\\r\\n    if (!c || isNaN(c[0]) || isNaN(c[1])) {\\r\\n      return null;\\r\\n    }\\r\\n    return new maptalks.Coordinate(c);\\r\\n  },\\r\\n};\\r\\n\\r\\nconst min = proj.project(new maptalks.Coordinate(-180, -90)),\\r\\n  max = proj.project(new maptalks.Coordinate(180, 90)),\\r\\n  fullExtent = {\\r\\n    top: max.y,\\r\\n    left: min.x,\\r\\n    right: max.x,\\r\\n    bottom: min.y,\\r\\n  };\\r\\n\\r\\nd3.json(\\"{res}/geojson/world-50m.json\\", function (error, world) {\\r\\n  if (error) throw error;\\r\\n  // initialize map with a customized projection\\r\\n  const map = new maptalks.Map(\\"map\\", {\\r\\n    center: [0, 0],\\r\\n    centerCross: true,\\r\\n    zoom: 2,\\r\\n    spatialReference: {\\r\\n      projection: proj,\\r\\n      resolutions: (function () {\\r\\n        const resolutions = [];\\r\\n        for (let i = 0; i < 10; i++) {\\r\\n          resolutions[i] = 4 / Math.pow(2, i);\\r\\n        }\\r\\n        return resolutions;\\r\\n      })(),\\r\\n      fullExtent: fullExtent,\\r\\n    },\\r\\n  });\\r\\n  const featureCollection = topojson.feature(world, world.objects.countries),\\r\\n    geometries = maptalks.GeoJSON.toGeometry(featureCollection);\\r\\n  const symbol = {\\r\\n    lineColor: \\"#fff\\",\\r\\n    lineWidth: 0.5,\\r\\n    polygonOpacity: 1,\\r\\n    polygonFill: \\"#747474\\",\\r\\n  };\\r\\n  new maptalks.VectorLayer(\\"v\\", geometries, {\\r\\n    geometryEvents: false,\\r\\n    enableSimplify: false,\\r\\n  })\\r\\n    .forEach(function (geo) {\\r\\n      geo.setSymbol(symbol);\\r\\n    })\\r\\n    .addTo(map);\\r\\n});\\r\\n"}},{"path":"basic/tilelayer-projection/different-projection","category":"basic","subcategory":"tilelayer-projection","name":"different-projection","html":"<div id=\\"map\\" class=\\"container\\"></div>\\r\\n\\r\\n<script type=\\"module\\">\\r\\n  import { Map, TileLayer } from \\"maptalks\\";\\r\\n\\r\\n  // load 3857 tiles in a map with 4326 projection\\r\\n  const map = new Map(\\"map\\", {\\r\\n    center: [-0.113049, 51.498568],\\r\\n    zoom: 9,\\r\\n    minZoom: 4,\\r\\n    maxZoom: 18,\\r\\n    spatialReference: {\\r\\n      projection: \\"EPSG:4326\\",\\r\\n    },\\r\\n    baseLayer: new TileLayer(\\"base\\", {\\r\\n      spatialReference: {\\r\\n        projection: \\"EPSG:3857\\",\\r\\n        // other properties necessary for spatial reference\\r\\n      },\\r\\n      urlTemplate:\\r\\n        \\"https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}.png\\",\\r\\n      subdomains: [\\"a\\", \\"b\\", \\"c\\", \\"d\\"],\\r\\n      attribution:\\r\\n        \\"&copy; <a href='http://osm.org'>OpenStreetMap</a> contributors, &copy; <a href='https://carto.com/'>CARTO</a>\\",\\r\\n    }),\\r\\n  });\\r\\n<\/script>\\r\\n\\r\\n<style>\\r\\n  @import \\"https://maptalks.com/api/maptalks.css\\";\\r\\n  @import \\"./index.css\\";\\r\\n</style>\\r\\n","description":"","files":{"index.css":"html,\\r\\nbody {\\r\\n  margin: 0px;\\r\\n  height: 100%;\\r\\n  width: 100%;\\r\\n}\\r\\n\\r\\n.container {\\r\\n  width: 100%;\\r\\n  height: 100%;\\r\\n}\\r\\n","index.html":"<div id=\\"map\\" class=\\"container\\"></div>\\r\\n\\r\\n<script type=\\"module\\">\\r\\n  import { Map, TileLayer } from \\"maptalks\\";\\r\\n\\r\\n  // load 3857 tiles in a map with 4326 projection\\r\\n  const map = new Map(\\"map\\", {\\r\\n    center: [-0.113049, 51.498568],\\r\\n    zoom: 9,\\r\\n    minZoom: 4,\\r\\n    maxZoom: 18,\\r\\n    spatialReference: {\\r\\n      projection: \\"EPSG:4326\\",\\r\\n    },\\r\\n    baseLayer: new TileLayer(\\"base\\", {\\r\\n      spatialReference: {\\r\\n        projection: \\"EPSG:3857\\",\\r\\n        // other properties necessary for spatial reference\\r\\n      },\\r\\n      urlTemplate:\\r\\n        \\"https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}.png\\",\\r\\n      subdomains: [\\"a\\", \\"b\\", \\"c\\", \\"d\\"],\\r\\n      attribution:\\r\\n        \\"&copy; <a href='http://osm.org'>OpenStreetMap</a> contributors, &copy; <a href='https://carto.com/'>CARTO</a>\\",\\r\\n    }),\\r\\n  });\\r\\n<\/script>\\r\\n\\r\\n<style>\\r\\n  @import \\"https://maptalks.com/api/maptalks.css\\";\\r\\n  @import \\"./index.css\\";\\r\\n</style>\\r\\n"}},{"path":"basic/tilelayer-projection/epsg4326","category":"basic","subcategory":"tilelayer-projection","name":"epsg4326","html":"<div id=\\"map\\" class=\\"container\\"></div>\\r\\n\\r\\n<script type=\\"module\\">\\r\\n  import { Map, TileLayer } from \\"maptalks\\";\\r\\n\\r\\n  const map = new Map(\\"map\\", {\\r\\n    center: [105.08052356963802, 36.04231948670001],\\r\\n    zoom: 4,\\r\\n    minZoom: 1,\\r\\n    maxZoom: 18,\\r\\n    spatialReference: {\\r\\n      projection: \\"EPSG:4326\\",\\r\\n    },\\r\\n    baseLayer: new TileLayer(\\"base\\", {\\r\\n      tileSystem: [1, -1, -180, 90],\\r\\n      urlTemplate:\\r\\n        \\"https://t{s}.tianditu.gov.cn/vec_c/wmts?SERVICE=WMTS&REQUEST=GetTile&VERSION=1.0.0&LAYER=vec&STYLE=default&TILEMATRIXSET=c&FORMAT=tiles&TILEMATRIX={z}&TILEROW={y}&TILECOL={x}&tk=6901643c38b65f1f9770196343cf72b2\\",\\r\\n      subdomains: [\\"1\\", \\"2\\", \\"3\\", \\"4\\", \\"5\\"],\\r\\n      attribution:\\r\\n        '&copy; <a target=\\"_blank\\" href=\\"http://www.tianditu.cn\\">Tianditu</a>',\\r\\n    }),\\r\\n  });\\r\\n<\/script>\\r\\n\\r\\n<style>\\r\\n  @import \\"https://maptalks.com/api/maptalks.css\\";\\r\\n  @import \\"./index.css\\";\\r\\n</style>\\r\\n","description":"","files":{"index.css":"html,\\r\\nbody {\\r\\n  margin: 0px;\\r\\n  height: 100%;\\r\\n  width: 100%;\\r\\n}\\r\\n\\r\\n.container {\\r\\n  width: 100%;\\r\\n  height: 100%;\\r\\n}\\r\\n","index.html":"<div id=\\"map\\" class=\\"container\\"></div>\\r\\n\\r\\n<script type=\\"module\\">\\r\\n  import { Map, TileLayer } from \\"maptalks\\";\\r\\n\\r\\n  const map = new Map(\\"map\\", {\\r\\n    center: [105.08052356963802, 36.04231948670001],\\r\\n    zoom: 4,\\r\\n    minZoom: 1,\\r\\n    maxZoom: 18,\\r\\n    spatialReference: {\\r\\n      projection: \\"EPSG:4326\\",\\r\\n    },\\r\\n    baseLayer: new TileLayer(\\"base\\", {\\r\\n      tileSystem: [1, -1, -180, 90],\\r\\n      urlTemplate:\\r\\n        \\"https://t{s}.tianditu.gov.cn/vec_c/wmts?SERVICE=WMTS&REQUEST=GetTile&VERSION=1.0.0&LAYER=vec&STYLE=default&TILEMATRIXSET=c&FORMAT=tiles&TILEMATRIX={z}&TILEROW={y}&TILECOL={x}&tk=6901643c38b65f1f9770196343cf72b2\\",\\r\\n      subdomains: [\\"1\\", \\"2\\", \\"3\\", \\"4\\", \\"5\\"],\\r\\n      attribution:\\r\\n        '&copy; <a target=\\"_blank\\" href=\\"http://www.tianditu.cn\\">Tianditu</a>',\\r\\n    }),\\r\\n  });\\r\\n<\/script>\\r\\n\\r\\n<style>\\r\\n  @import \\"https://maptalks.com/api/maptalks.css\\";\\r\\n  @import \\"./index.css\\";\\r\\n</style>\\r\\n"}},{"path":"basic/tilelayer-projection/filter","category":"basic","subcategory":"tilelayer-projection","name":"filter","html":"<div id=\\"map\\" class=\\"container\\"></div>\\r\\n\\r\\n<script type=\\"module\\">\\r\\n  import { Map, TileLayer } from \\"maptalks\\";\\r\\n\\r\\n  const map = new Map(\\"map\\", {\\r\\n    center: [105.08052356963802, 36.04231948670001],\\r\\n    zoom: 5,\\r\\n    minZoom: 1,\\r\\n    maxZoom: 19,\\r\\n    baseLayer: new TileLayer(\\"base\\", {\\r\\n      urlTemplate:\\r\\n        \\"https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}.png\\",\\r\\n      subdomains: [\\"a\\", \\"b\\", \\"c\\", \\"d\\"],\\r\\n      attribution:\\r\\n        \\"&copy; <a href='http://osm.org'>OpenStreetMap</a> contributors, &copy; <a href='https://carto.com/'>CARTO</a>\\",\\r\\n\\r\\n      // css filter\\r\\n      cssFilter: \\"sepia(100%) invert(90%)\\",\\r\\n    }),\\r\\n  });\\r\\n<\/script>\\r\\n\\r\\n<style>\\r\\n  @import \\"https://maptalks.com/api/maptalks.css\\";\\r\\n  @import \\"./index.css\\";\\r\\n</style>\\r\\n","description":"","files":{"index.css":"html,\\r\\nbody {\\r\\n  margin: 0px;\\r\\n  height: 100%;\\r\\n  width: 100%;\\r\\n}\\r\\n\\r\\n.container {\\r\\n  width: 100%;\\r\\n  height: 100%;\\r\\n}\\r\\n","index.html":"<div id=\\"map\\" class=\\"container\\"></div>\\r\\n\\r\\n<script type=\\"module\\">\\r\\n  import { Map, TileLayer } from \\"maptalks\\";\\r\\n\\r\\n  const map = new Map(\\"map\\", {\\r\\n    center: [105.08052356963802, 36.04231948670001],\\r\\n    zoom: 5,\\r\\n    minZoom: 1,\\r\\n    maxZoom: 19,\\r\\n    baseLayer: new TileLayer(\\"base\\", {\\r\\n      urlTemplate:\\r\\n        \\"https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}.png\\",\\r\\n      subdomains: [\\"a\\", \\"b\\", \\"c\\", \\"d\\"],\\r\\n      attribution:\\r\\n        \\"&copy; <a href='http://osm.org'>OpenStreetMap</a> contributors, &copy; <a href='https://carto.com/'>CARTO</a>\\",\\r\\n\\r\\n      // css filter\\r\\n      cssFilter: \\"sepia(100%) invert(90%)\\",\\r\\n    }),\\r\\n  });\\r\\n<\/script>\\r\\n\\r\\n<style>\\r\\n  @import \\"https://maptalks.com/api/maptalks.css\\";\\r\\n  @import \\"./index.css\\";\\r\\n</style>\\r\\n"}},{"path":"basic/tilelayer-projection/grouptilelayer","category":"basic","subcategory":"tilelayer-projection","name":"grouptilelayer","html":"<div id=\\"map\\" class=\\"container\\"></div>\\r\\n\\r\\n<script type=\\"module\\">\\r\\n  import { GroupTileLayer, Map, TileLayer } from \\"maptalks\\";\\r\\n\\r\\n  const map = new Map(\\"map\\", {\\r\\n    center: [-0.113049, 51.498568],\\r\\n    zoom: 6,\\r\\n    pitch: 40,\\r\\n    attribution: {\\r\\n      content: \\" &copy; carto\\",\\r\\n    },\\r\\n    // add 2 TileLayers with a GroupTileLayer\\r\\n    baseLayer: new GroupTileLayer(\\"base\\", [\\r\\n      new TileLayer(\\"tile2\\", {\\r\\n        urlTemplate:\\r\\n          \\"https://{s}.basemaps.cartocdn.com/light_nolabels/{z}/{x}/{y}.png\\",\\r\\n        subdomains: [\\"a\\", \\"b\\", \\"c\\", \\"d\\"],\\r\\n      }),\\r\\n\\r\\n      new TileLayer(\\"boudaries\\", {\\r\\n        urlTemplate:\\r\\n          \\"https://{s}.basemaps.cartocdn.com/dark_only_labels/{z}/{x}/{y}.png\\",\\r\\n        subdomains: [\\"a\\", \\"b\\", \\"c\\", \\"d\\"],\\r\\n      }),\\r\\n    ]),\\r\\n  });\\r\\n<\/script>\\r\\n\\r\\n<style>\\r\\n  @import \\"https://maptalks.com/api/maptalks.css\\";\\r\\n  @import \\"./index.css\\";\\r\\n</style>\\r\\n","description":"","files":{"index.css":"html,\\r\\nbody {\\r\\n  margin: 0px;\\r\\n  height: 100%;\\r\\n  width: 100%;\\r\\n}\\r\\n\\r\\n.container {\\r\\n  width: 100%;\\r\\n  height: 100%;\\r\\n}\\r\\n","index.html":"<div id=\\"map\\" class=\\"container\\"></div>\\r\\n\\r\\n<script type=\\"module\\">\\r\\n  import { GroupTileLayer, Map, TileLayer } from \\"maptalks\\";\\r\\n\\r\\n  const map = new Map(\\"map\\", {\\r\\n    center: [-0.113049, 51.498568],\\r\\n    zoom: 6,\\r\\n   